// Real pgjdbc 42.7.x against STASK and PostgreSQL 16. Single-file source:
//   java -cp postgresql-42.7.14.jar Jdbc.java <host:port> <user> <password> [extra url params]
// Every operation prints one line:  OK|FAIL <op> :: <result or SQLSTATE: message>   (results are deterministic so two targets can be diffed)
import java.math.BigDecimal;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.function.*;

public class Jdbc {
    static Connection c;
    static int fails = 0, ok = 0;
    interface Op { String run() throws Exception; }
    static void op(String name, Op o) {
        try { String r = o.run(); ok++; System.out.println("OK   " + name + " :: " + r); }
        catch (Throwable t) {
            fails++;
            String st = t instanceof SQLException se ? se.getSQLState() : t.getClass().getSimpleName();
            try { if (c != null && !c.getAutoCommit() && !c.isClosed()) c.rollback(); } catch (Exception e) { }
            System.out.println("FAIL " + name + " :: " + st + ": " + String.valueOf(t.getMessage()).replace('\n', ' '));
        }
    }
    static String rows(ResultSet rs, String... cols) throws SQLException {
        List<String> out = new ArrayList<>();
        ResultSetMetaData md = rs.getMetaData();
        while (rs.next()) {
            StringBuilder sb = new StringBuilder();
            if (cols.length == 0) for (int i = 1; i <= md.getColumnCount(); i++) sb.append(rs.getString(i)).append('|');
            else for (String col : cols) sb.append(rs.getString(col)).append('|');
            out.add(sb.toString());
        }
        Collections.sort(out);
        return out.size() + " rows " + out;
    }
    static void exec(String sql) throws SQLException { try (Statement s = c.createStatement()) { s.execute(sql); } }
    static long count(String sql) throws SQLException { try (Statement s = c.createStatement(); ResultSet r = s.executeQuery(sql)) { r.next(); return r.getLong(1); } }

    public static void main(String[] a) throws Exception {
        String url = "jdbc:postgresql://" + a[0] + "/stask?sslmode=disable" + (a.length > 3 ? "&" + a[3] : "");
        Properties p = new Properties(); p.setProperty("user", a[1]); p.setProperty("password", a[2]);
        c = DriverManager.getConnection(url, p);
        DatabaseMetaData md = c.getMetaData();
        op("connect/product", () -> md.getDatabaseProductName() + " " + md.getDatabaseMajorVersion() + "." + md.getDatabaseMinorVersion() + " driver " + md.getDriverVersion());
        for (String t : new String[]{"jt_c", "jt_t", "jt_s"}) { try { exec("drop table if exists " + t + " cascade"); } catch (Exception e) { } }
        op("ddl/create jt_t", () -> { exec("create table jt_t(id bigint primary key, u uuid, n numeric(19,2), ts timestamp, tstz timestamptz, d date, b bytea, t text, ia int[], ta text[], bo boolean, f8 double precision, s smallint, v varchar(30) not null default 'x')"); return "ok"; });
        op("ddl/create jt_c with fk+unique", () -> { exec("create table jt_c(id int primary key, t_id bigint references jt_t(id), name varchar(40) unique)"); return "ok"; });
        op("ddl/create index composite", () -> { exec("create index jt_idx on jt_t(n, ts)"); return "ok"; });
        op("ddl/create index single", () -> { exec("create unique index jt_idx_v on jt_t(v, id)"); return "ok"; });
        op("ddl/create jt_s", () -> { exec("create table jt_s(id bigint generated by default as identity primary key, x text)"); return "ok"; });

        // ---- DatabaseMetaData
        op("meta/getCatalogs", () -> { try (ResultSet r = md.getCatalogs()) { return rows(r).contains("stask") ? "has stask" : "no stask: " + rows(r); } });
        op("meta/getSchemas", () -> { try (ResultSet r = md.getSchemas()) { String s = rows(r, "TABLE_SCHEM"); return s.contains("public") ? "has public" : s; } });
        op("meta/getTableTypes", () -> { try (ResultSet r = md.getTableTypes()) { String s = rows(r); return s.contains("TABLE|") + " " + s.contains("VIEW|"); } });
        op("meta/getTables", () -> { try (ResultSet r = md.getTables(null, "public", "jt_%", new String[]{"TABLE"})) { return rows(r, "TABLE_SCHEM", "TABLE_NAME", "TABLE_TYPE"); } });
        op("meta/getTables(null,null,%,null) contains jt_t", () -> { try (ResultSet r = md.getTables(null, null, "%", null)) { String s = rows(r, "TABLE_NAME"); return s.contains("jt_t|") + ""; } });
        op("meta/getColumns", () -> { try (ResultSet r = md.getColumns(null, "public", "jt_t", "%")) { return rows(r, "COLUMN_NAME", "DATA_TYPE", "TYPE_NAME", "COLUMN_SIZE", "DECIMAL_DIGITS", "IS_NULLABLE", "COLUMN_DEF", "ORDINAL_POSITION", "IS_AUTOINCREMENT"); } });
        op("meta/getColumns identity jt_s", () -> { try (ResultSet r = md.getColumns(null, "public", "jt_s", "%")) { return rows(r, "COLUMN_NAME", "TYPE_NAME", "IS_AUTOINCREMENT", "IS_GENERATEDCOLUMN"); } });
        op("meta/getPrimaryKeys jt_t", () -> { try (ResultSet r = md.getPrimaryKeys(null, "public", "jt_t")) { return rows(r, "TABLE_NAME", "COLUMN_NAME", "KEY_SEQ", "PK_NAME"); } });
        op("meta/getPrimaryKeys jt_c", () -> { try (ResultSet r = md.getPrimaryKeys(null, "public", "jt_c")) { return rows(r, "TABLE_NAME", "COLUMN_NAME", "KEY_SEQ", "PK_NAME"); } });
        op("meta/getIndexInfo jt_t (composite index)", () -> { try (ResultSet r = md.getIndexInfo(null, "public", "jt_t", false, false)) { return rows(r, "INDEX_NAME", "NON_UNIQUE", "ORDINAL_POSITION", "COLUMN_NAME", "ASC_OR_DESC"); } });
        op("meta/getIndexInfo jt_c (unique)", () -> { try (ResultSet r = md.getIndexInfo(null, "public", "jt_c", true, false)) { return rows(r, "INDEX_NAME", "NON_UNIQUE", "ORDINAL_POSITION", "COLUMN_NAME"); } });
        op("meta/getImportedKeys jt_c", () -> { try (ResultSet r = md.getImportedKeys(null, "public", "jt_c")) { return rows(r, "PKTABLE_NAME", "PKCOLUMN_NAME", "FKTABLE_NAME", "FKCOLUMN_NAME", "KEY_SEQ", "UPDATE_RULE", "DELETE_RULE", "FK_NAME", "PK_NAME", "DEFERRABILITY"); } });
        op("meta/getExportedKeys jt_t", () -> { try (ResultSet r = md.getExportedKeys(null, "public", "jt_t")) { return rows(r, "PKTABLE_NAME", "PKCOLUMN_NAME", "FKTABLE_NAME", "FKCOLUMN_NAME", "FK_NAME"); } });
        op("meta/getCrossReference", () -> { try (ResultSet r = md.getCrossReference(null, "public", "jt_t", null, "public", "jt_c")) { return rows(r, "PKTABLE_NAME", "FKTABLE_NAME"); } });
        op("meta/getTypeInfo", () -> { try (ResultSet r = md.getTypeInfo()) { int n = 0; boolean uuid = false, numeric = false; while (r.next()) { n++; String t = r.getString("TYPE_NAME"); uuid |= "uuid".equals(t); numeric |= "numeric".equals(t); } return "types>=30:" + (n >= 30) + " uuid:" + uuid + " numeric:" + numeric; } });
        op("meta/getFunctions", () -> { try (ResultSet r = md.getFunctions(null, "public", "%")) { int n = 0; while (r.next()) n++; return "ok"; } });
        op("meta/getSequences-ish via getTables(SEQUENCE)", () -> { try (ResultSet r = md.getTables(null, "public", "%", new String[]{"SEQUENCE"})) { return rows(r, "TABLE_NAME"); } });
        op("meta/getBestRowIdentifier", () -> { try (ResultSet r = md.getBestRowIdentifier(null, "public", "jt_t", DatabaseMetaData.bestRowSession, false)) { return rows(r, "COLUMN_NAME"); } });
        op("meta/getVersionColumns", () -> { try (ResultSet r = md.getVersionColumns(null, "public", "jt_t")) { return rows(r, "COLUMN_NAME"); } });
        op("meta/getProcedures", () -> { try (ResultSet r = md.getProcedures(null, "public", "%")) { return "ok"; } });
        op("meta/getUDTs-like getColumns uuid type", () -> { try (ResultSet r = md.getColumns(null, "public", "jt_t", "u")) { r.next(); return r.getString("TYPE_NAME") + " " + r.getInt("DATA_TYPE"); } });

        op("meta/getPrimaryKeys composite PK (a,b)", () -> { exec("drop table if exists jt_cpk"); exec("create table jt_cpk(a int, b int, c text, primary key(a,b))"); try (ResultSet r = md.getPrimaryKeys(null, "public", "jt_cpk")) { return rows(r, "COLUMN_NAME", "KEY_SEQ", "PK_NAME"); } });
        op("meta/getIndexInfo composite PK table", () -> { try (ResultSet r = md.getIndexInfo(null, "public", "jt_cpk", false, false)) { return rows(r, "INDEX_NAME", "ORDINAL_POSITION", "COLUMN_NAME"); } });

        // ---- PreparedStatement types round trip
        UUID uid = UUID.fromString("123e4567-e89b-12d3-a456-426614174000");
        op("ps/insert all types", () -> {
            try (PreparedStatement ps = c.prepareStatement("insert into jt_t(id,u,n,ts,tstz,d,b,t,ia,ta,bo,f8,s) values (?,?,?,?,?,?::date,?,?,?::int4[],?::text[],?,?,?)")) {
                ps.setLong(1, 1); ps.setObject(2, uid); ps.setBigDecimal(3, new BigDecimal("12345678901234567.89"));
                ps.setTimestamp(4, Timestamp.valueOf("2026-03-04 05:06:07.123456"));
                ps.setObject(5, OffsetDateTime.of(2026, 3, 4, 5, 6, 7, 0, ZoneOffset.ofHours(7)));
                ps.setString(6, "2026-03-04"); ps.setBytes(7, new byte[]{0, 1, 2, (byte) 255, 'a'});
                ps.setString(8, "héllo tiếng Việt"); ps.setString(9, "{1,2,3}");
                ps.setString(10, "{a,\"b,c\",NULL}"); ps.setBoolean(11, true); ps.setDouble(12, 1.5); ps.setShort(13, (short) 7);
                return "rows=" + ps.executeUpdate();
            }
        });
        op("ps/setDate(java.sql.Date) into date column", () -> { try (PreparedStatement ps = c.prepareStatement("insert into jt_t(id,d) values (?,?)")) { ps.setLong(1, 3); ps.setDate(2, java.sql.Date.valueOf("2026-03-04")); ps.executeUpdate(); return "d=" + count("select count(*) from jt_t where id=3 and d = date '2026-03-04'"); } });
        op("ps/setObject(LocalDate) into date column", () -> { try (PreparedStatement ps = c.prepareStatement("insert into jt_t(id,d) values (?,?)")) { ps.setLong(1, 4); ps.setObject(2, LocalDate.of(2026, 3, 4)); ps.executeUpdate(); return "ok"; } });
        op("ps/setObject(LocalDateTime) into timestamp", () -> { try (PreparedStatement ps = c.prepareStatement("insert into jt_t(id,ts) values (?,?)")) { ps.setLong(1, 5); ps.setObject(2, LocalDateTime.of(2026, 3, 4, 5, 6, 7)); ps.executeUpdate(); return "ok"; } });
        op("ps/setArray(createArrayOf int4) insert", () -> { try (PreparedStatement ps = c.prepareStatement("insert into jt_t(id,ia) values (?,?)")) { ps.setLong(1, 6); ps.setArray(2, c.createArrayOf("int4", new Integer[]{1, 2})); return "rows=" + ps.executeUpdate(); } });
        op("ps/setArray(createArrayOf text) insert", () -> { try (PreparedStatement ps = c.prepareStatement("insert into jt_t(id,ta) values (?,?)")) { ps.setLong(1, 7); ps.setArray(2, c.createArrayOf("text", new String[]{"x", "y"})); return "rows=" + ps.executeUpdate(); } });
        op("ps/select all types back", () -> {
            try (PreparedStatement ps = c.prepareStatement("select u,n,ts,tstz,d,b,t,ia,ta,bo,f8,s from jt_t where id=?")) {
                ps.setLong(1, 1);
                try (ResultSet r = ps.executeQuery()) {
                    r.next();
                    return "uuid=" + r.getObject(1, UUID.class) + " n=" + r.getBigDecimal(2) + " ts=" + r.getTimestamp(3) + " tstz=" + r.getObject(4, OffsetDateTime.class).toInstant()
                        + " d=" + r.getDate(5) + " b=" + Arrays.toString(r.getBytes(6)) + " t=" + r.getString(7) + " ia=" + Arrays.toString((Integer[]) r.getArray(8).getArray())
                        + " ta=" + Arrays.toString((String[]) r.getArray(9).getArray()) + " bo=" + r.getBoolean(10) + " f8=" + r.getDouble(11) + " s=" + r.getShort(12);
                }
            }
        });
        op("ps/setNull typed + select is null", () -> {
            try (PreparedStatement ps = c.prepareStatement("insert into jt_t(id,u,n,ts,b,t,ia) values (?,?,?,?,?,?,?)")) {
                ps.setLong(1, 2); ps.setNull(2, Types.OTHER); ps.setNull(3, Types.NUMERIC); ps.setNull(4, Types.TIMESTAMP); ps.setNull(5, Types.BINARY); ps.setNull(6, Types.VARCHAR); ps.setNull(7, Types.ARRAY);
                return "rows=" + ps.executeUpdate() + " nulls=" + count("select count(*) from jt_t where id=2 and u is null and n is null and ts is null and b is null and t is null and ia is null");
            }
        });
        op("ps/uuid param compare (where u = ?)", () -> { try (PreparedStatement ps = c.prepareStatement("select id from jt_t where u = ?")) { ps.setObject(1, uid); try (ResultSet r = ps.executeQuery()) { return rows(r); } } });
        op("ps/uuid param as string cast (u = ?::uuid)", () -> { try (PreparedStatement ps = c.prepareStatement("select id from jt_t where u = ?::uuid")) { ps.setString(1, uid.toString()); try (ResultSet r = ps.executeQuery()) { return rows(r); } } });
        op("ps/numeric arithmetic param", () -> { try (PreparedStatement ps = c.prepareStatement("select ? + n from jt_t where id=1")) { ps.setBigDecimal(1, new BigDecimal("0.11")); try (ResultSet r = ps.executeQuery()) { r.next(); return r.getBigDecimal(1).toPlainString(); } } });
        op("ps/= ANY(?) with array param", () -> { try (PreparedStatement ps = c.prepareStatement("select id from jt_t where id = any(?)")) { ps.setArray(1, c.createArrayOf("int8", new Long[]{1L, 2L, 9L})); try (ResultSet r = ps.executeQuery()) { return rows(r); } } });
        op("ps/IN (?,?,?)", () -> { try (PreparedStatement ps = c.prepareStatement("select id from jt_t where id in (?,?,?)")) { ps.setLong(1, 1); ps.setLong(2, 2); ps.setLong(3, 3); try (ResultSet r = ps.executeQuery()) { return rows(r); } } });
        op("ps/limit ? offset ?", () -> { try (PreparedStatement ps = c.prepareStatement("select id from jt_t order by id limit ? offset ?")) { ps.setInt(1, 1); ps.setInt(2, 1); try (ResultSet r = ps.executeQuery()) { return rows(r); } } });
        op("ps/timestamptz at time zone + extract", () -> { try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("select extract(year from tstz), to_char(ts,'YYYY-MM-DD HH24:MI:SS'), date_trunc('day', ts) from jt_t where id=1")) { r.next(); return r.getString(1) + " " + r.getString(2) + " " + r.getString(3); } });
        op("ps/server-prepared (prepareThreshold=1) repeated x7", () -> {
            try (PreparedStatement ps = c.prepareStatement("select n, t from jt_t where id = ?")) {
                ((org.postgresql.PGStatement) ps).setPrepareThreshold(1);
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < 7; i++) { ps.setLong(1, 1); try (ResultSet r = ps.executeQuery()) { r.next(); sb.append(r.getBigDecimal(1)).append(';'); } }
                return sb.toString();
            }
        });
        op("ps/Statement.executeQuery multi-type metadata", () -> {
            try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("select id,u,n,ts,tstz,d,b,t,ia,bo,f8,s from jt_t where id=1")) {
                ResultSetMetaData m = r.getMetaData(); StringBuilder sb = new StringBuilder();
                for (int i = 1; i <= m.getColumnCount(); i++) sb.append(m.getColumnName(i)).append(':').append(m.getColumnTypeName(i)).append('/').append(m.getColumnType(i)).append(' ');
                return sb.toString();
            }
        });

        // ---- batch insert
        op("batch/insert 1000 rows executeBatch", () -> {
            c.setAutoCommit(false);
            try (PreparedStatement ps = c.prepareStatement("insert into jt_t(id,n,t,v) values (?,?,?,?)")) {
                for (int i = 100; i < 1100; i++) { ps.setLong(1, i); ps.setBigDecimal(2, new BigDecimal(i + ".50")); ps.setString(3, "row" + i); ps.setString(4, "v" + i); ps.addBatch(); }
                int[] res = ps.executeBatch(); c.commit(); c.setAutoCommit(true);
                int sum = 0; for (int x : res) sum += (x == Statement.SUCCESS_NO_INFO ? 1 : x);
                return "results=" + res.length + " sum=" + sum + " count=" + count("select count(*) from jt_t where id>=100");
            }
        });
        op("batch/error in batch -> BatchUpdateException", () -> {
            c.setAutoCommit(false);
            try (PreparedStatement ps = c.prepareStatement("insert into jt_c(id,t_id,name) values (?,?,?)")) {
                ps.setInt(1, 1); ps.setLong(2, 100); ps.setString(3, "a"); ps.addBatch();
                ps.setInt(1, 2); ps.setLong(2, 100); ps.setString(3, "a"); ps.addBatch(); // unique violation
                try { ps.executeBatch(); return "NO ERROR"; } catch (BatchUpdateException e) { c.rollback(); return "BatchUpdateException state=" + e.getSQLState() + " updateCounts=" + e.getUpdateCounts().length; }
            } finally { c.setAutoCommit(true); }
        });
        op("batch/reWriteBatchedInserts-style multi-values", () -> { try (PreparedStatement ps = c.prepareStatement("insert into jt_c(id,t_id,name) values (?,?,?),(?,?,?)")) { ps.setInt(1, 10); ps.setLong(2, 100); ps.setString(3, "m1"); ps.setInt(4, 11); ps.setLong(5, 101); ps.setString(6, "m2"); return "rows=" + ps.executeUpdate(); } });

        // ---- RETURNING / generated keys
        op("returning/insert ... returning id", () -> { try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("insert into jt_s(x) values ('a') returning id, x")) { r.next(); return r.getLong(1) + " " + r.getString(2); } });
        op("returning/getGeneratedKeys RETURN_GENERATED_KEYS", () -> { try (PreparedStatement ps = c.prepareStatement("insert into jt_s(x) values (?)", Statement.RETURN_GENERATED_KEYS)) { ps.setString(1, "b"); ps.executeUpdate(); try (ResultSet r = ps.getGeneratedKeys()) { r.next(); return "key=" + r.getLong(1); } } });
        op("returning/getGeneratedKeys column names", () -> { try (PreparedStatement ps = c.prepareStatement("insert into jt_s(x) values (?)", new String[]{"id"})) { ps.setString(1, "c"); ps.executeUpdate(); try (ResultSet r = ps.getGeneratedKeys()) { r.next(); return "key=" + r.getLong("id"); } } });
        op("returning/update returning", () -> { try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("update jt_s set x = x || '!' where x = 'a' returning x")) { r.next(); return r.getString(1); } });
        op("returning/delete returning", () -> { try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("delete from jt_c where id = 10 returning id")) { r.next(); return "" + r.getInt(1); } });

        // ---- transactions, savepoints
        op("tx/commit", () -> { c.setAutoCommit(false); exec("insert into jt_s(x) values ('tx1')"); c.commit(); c.setAutoCommit(true); return "n=" + count("select count(*) from jt_s where x='tx1'"); });
        op("tx/rollback", () -> { c.setAutoCommit(false); exec("insert into jt_s(x) values ('tx2')"); c.rollback(); c.setAutoCommit(true); return "n=" + count("select count(*) from jt_s where x='tx2'"); });
        op("tx/savepoint rollback + release", () -> {
            c.setAutoCommit(false);
            exec("insert into jt_s(x) values ('sp0')");
            Savepoint s1 = c.setSavepoint("s1"); exec("insert into jt_s(x) values ('sp1')");
            Savepoint s2 = c.setSavepoint(); exec("insert into jt_s(x) values ('sp2')");
            c.rollback(s1); exec("insert into jt_s(x) values ('sp3')");
            c.releaseSavepoint(s1); c.commit(); c.setAutoCommit(true);
            try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("select x from jt_s where x like 'sp%' order by x")) { return rows(r); }
        });
        op("tx/error aborts tx; rollback to savepoint recovers", () -> {
            c.setAutoCommit(false);
            exec("insert into jt_s(x) values ('ab0')"); Savepoint s = c.setSavepoint("e");
            String st1 = "-"; try { exec("insert into jt_c(id,t_id,name) values (99, 424242, 'fkviol')"); } catch (SQLException e) { st1 = e.getSQLState(); }
            String st2 = "-"; try { exec("select 1"); } catch (SQLException e) { st2 = e.getSQLState(); }
            c.rollback(s); exec("insert into jt_s(x) values ('ab1')"); c.commit(); c.setAutoCommit(true);
            return "fk=" + st1 + " afterError=" + st2 + " n=" + count("select count(*) from jt_s where x like 'ab%'");
        });
        op("tx/isolation serializable + read committed set", () -> { c.setTransactionIsolation(Connection.TRANSACTION_SERIALIZABLE); int a1 = c.getTransactionIsolation(); c.setTransactionIsolation(Connection.TRANSACTION_READ_COMMITTED); return a1 + "," + c.getTransactionIsolation(); });
        op("tx/readOnly", () -> { c.setReadOnly(true); String r; try { exec("insert into jt_s(x) values ('ro')"); r = "write allowed"; } catch (SQLException e) { r = e.getSQLState(); } c.setReadOnly(false); return r; });

        // ---- cursor / fetch size
        op("fetchsize/cursor 100 over 1000+ rows", () -> {
            c.setAutoCommit(false);
            try (Statement s = c.createStatement()) {
                s.setFetchSize(100);
                try (ResultSet r = s.executeQuery("select id, t from jt_t where id >= 100 order by id")) { int n = 0; long sum = 0; while (r.next()) { n++; sum += r.getLong(1); } c.commit(); return "n=" + n + " sum=" + sum; }
            } finally { c.setAutoCommit(true); }
        });
        op("fetchsize/prepared 50 + early close", () -> {
            c.setAutoCommit(false);
            try (PreparedStatement ps = c.prepareStatement("select id from jt_t where id >= 100 order by id")) {
                ps.setFetchSize(50);
                try (ResultSet r = ps.executeQuery()) { r.next(); r.next(); }
                c.commit(); return "closed early ok, " + count("select 1");
            } finally { c.setAutoCommit(true); }
        });
        op("fetchsize/two cursors interleaved", () -> {
            c.setAutoCommit(false);
            try (Statement s1 = c.createStatement(); Statement s2 = c.createStatement()) {
                s1.setFetchSize(10); s2.setFetchSize(10);
                try (ResultSet r1 = s1.executeQuery("select id from jt_t where id>=100 order by id"); ResultSet r2 = s2.executeQuery("select id from jt_t where id>=100 order by id desc")) {
                    long a1 = 0, b1 = 0; for (int i = 0; i < 25; i++) { r1.next(); a1 += r1.getLong(1); r2.next(); b1 += r2.getLong(1); } c.commit(); return a1 + "/" + b1;
                }
            } finally { c.setAutoCommit(true); }
        });
        op("rs/scrollable insensitive", () -> { try (Statement s = c.createStatement(ResultSet.TYPE_SCROLL_INSENSITIVE, ResultSet.CONCUR_READ_ONLY); ResultSet r = s.executeQuery("select id from jt_t where id<=2 order by id")) { r.last(); int n = r.getRow(); r.first(); return n + " first=" + r.getLong(1); } });
        op("rs/updatable resultset", () -> { try (Statement s = c.createStatement(ResultSet.TYPE_SCROLL_INSENSITIVE, ResultSet.CONCUR_UPDATABLE); ResultSet r = s.executeQuery("select id, x from jt_s where x = 'tx1'")) { r.next(); r.updateString("x", "tx1u"); r.updateRow(); return "n=" + count("select count(*) from jt_s where x='tx1u'"); } });


        // ---- Jmix/Hibernate-style access patterns
        op("jmix/uuid pk table: insert, select by uuid param, update, join on uuid, delete", () -> {
            try { exec("drop table if exists jt_u2"); exec("drop table if exists jt_u"); } catch (Exception e) { }
            exec("create table jt_u(id uuid primary key, version int not null default 1, name varchar(50), amount numeric(19,2), created timestamp)");
            exec("create table jt_u2(id uuid primary key, u_id uuid, note text)");
            UUID a1 = UUID.randomUUID();
            try (PreparedStatement ps = c.prepareStatement("insert into jt_u(id, name, amount, created) values (?,?,?,?)")) { ps.setObject(1, a1); ps.setString(2, "n1"); ps.setBigDecimal(3, new BigDecimal("10.10")); ps.setTimestamp(4, Timestamp.valueOf("2026-01-01 00:00:00")); ps.executeUpdate(); }
            try (PreparedStatement ps = c.prepareStatement("insert into jt_u2(id, u_id, note) values (?,?,?)")) { ps.setObject(1, UUID.randomUUID()); ps.setObject(2, a1); ps.setString(3, "child"); ps.executeUpdate(); }
            int upd; try (PreparedStatement ps = c.prepareStatement("update jt_u set name = ?, version = version + 1 where id = ? and version = ?")) { ps.setString(1, "n1b"); ps.setObject(2, a1); ps.setInt(3, 1); upd = ps.executeUpdate(); }
            String got; try (PreparedStatement ps = c.prepareStatement("select e.name, e.version, d.note from jt_u e join jt_u2 d on d.u_id = e.id where e.id = ?")) { ps.setObject(1, a1); try (ResultSet r = ps.executeQuery()) { r.next(); got = r.getString(1) + "/" + r.getInt(2) + "/" + r.getString(3); } }
            int del; try (PreparedStatement ps = c.prepareStatement("delete from jt_u2 where u_id = ?")) { ps.setObject(1, a1); del = ps.executeUpdate(); }
            return "upd=" + upd + " got=" + got + " del=" + del;
        });
        op("jmix/select ... for update", () -> { c.setAutoCommit(false); try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("select id from jt_u for update")) { r.next(); c.commit(); return "ok"; } finally { c.setAutoCommit(true); } });
        op("jmix/select ... for update skip locked", () -> { c.setAutoCommit(false); try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("select id from jt_u for update skip locked")) { c.commit(); return "ok"; } finally { c.setAutoCommit(true); } });
        op("jmix/insert on conflict do nothing (pk)", () -> { exec("insert into jt_s(id,x) values (900,'oc') on conflict (id) do nothing"); exec("insert into jt_s(id,x) values (900,'oc2') on conflict (id) do nothing"); return "n=" + count("select count(*) from jt_s where id=900"); });
        op("jmix/lower(col) like lower(?) + ilike", () -> { try (PreparedStatement ps = c.prepareStatement("select count(*) from jt_t where lower(t) like lower(?) and t ilike ?")) { ps.setString(1, "%ROW1%"); ps.setString(2, "%row1%"); try (ResultSet r = ps.executeQuery()) { r.next(); return "" + r.getLong(1); } } });
        op("jmix/count + order by + limit offset paging", () -> { try (PreparedStatement ps = c.prepareStatement("select id, t from jt_t where id >= ? order by t desc, id limit ? offset ?")) { ps.setLong(1, 100); ps.setInt(2, 3); ps.setInt(3, 5); try (ResultSet r = ps.executeQuery()) { return rows(r); } } });
        op("jmix/nextval + currval + sequence via select", () -> { exec("drop sequence if exists jt_seq"); exec("create sequence jt_seq start 5"); try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("select nextval('jt_seq'), nextval('jt_seq')")) { r.next(); return r.getLong(1) + "," + r.getLong(2); } });
        op("jmix/multi-statement simple query", () -> { try (Statement s = c.createStatement()) { boolean rs = s.execute("select 1; select 2 as two"); int n = 0; do { if (rs) { try (ResultSet r = s.getResultSet()) { r.next(); n += r.getInt(1); } } rs = s.getMoreResults(); } while (rs); return "sum=" + n; } });
        op("jmix/resultset metadata base table (getTableName/isNullable/isAutoIncrement)", () -> { try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("select id, x from jt_s")) { ResultSetMetaData m = r.getMetaData(); return m.getTableName(1) + "|" + m.getSchemaName(1) + "|" + m.isNullable(1) + "|" + m.isAutoIncrement(1) + "|" + m.getTableName(2); } });
        op("jmix/aggregate types: sum(int), avg, count(distinct)", () -> { try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("select sum(s), avg(n), count(distinct v), max(ts), min(n) from jt_t")) { ResultSetMetaData m = r.getMetaData(); r.next(); return m.getColumnTypeName(1) + " " + m.getColumnTypeName(2) + " " + m.getColumnTypeName(3) + " " + r.getBigDecimal(2).scale(); } });
        op("jmix/transaction w/ DDL (create table in tx, rollback)", () -> { c.setAutoCommit(false); exec("create table jt_ddltx(a int)"); c.rollback(); c.setAutoCommit(true); try (ResultSet r = c.getMetaData().getTables(null, "public", "jt_ddltx", null)) { return r.next() ? "table survived rollback" : "rolled back"; } });

        // ---- COPY via CopyManager
        op("copy/copyIn csv", () -> { org.postgresql.copy.CopyManager cm = ((org.postgresql.PGConnection) c).getCopyAPI(); long n = cm.copyIn("copy jt_s(x) from stdin with (format csv)", new java.io.StringReader("cp1\ncp2\n\"cp,3\"\n")); return "n=" + n + " have=" + count("select count(*) from jt_s where x like 'cp%'"); });
        op("copy/copyOut csv", () -> { org.postgresql.copy.CopyManager cm = ((org.postgresql.PGConnection) c).getCopyAPI(); java.io.StringWriter w = new java.io.StringWriter(); long n = cm.copyOut("copy (select x from jt_s where x like 'cp%' order by x) to stdout with (format csv)", w); return "n=" + n + " " + w.toString().replace("\n", "\\n"); });

        // ---- error SQLSTATEs
        op("err/unique violation 23505", () -> expectState("insert into jt_c(id,t_id,name) values (50,100,'dup1'),(51,100,'dup1')", "23505"));
        op("err/fk violation 23503", () -> expectState("insert into jt_c(id,t_id,name) values (60,999999,'fk')", "23503"));
        op("err/not null 23502", () -> expectState("insert into jt_t(id, v) values (7777, null)", "23502"));
        op("err/pk duplicate 23505", () -> expectState("insert into jt_t(id) values (1)", "23505"));
        op("err/syntax 42601", () -> expectState("selec 1", "42601"));
        op("err/undefined table 42P01", () -> expectState("select * from no_such_t", "42P01"));
        op("err/undefined column 42703", () -> expectState("select nope from jt_t", "42703"));
        op("err/division by zero 22012", () -> expectState("select 1/0", "22012"));
        op("err/invalid text rep 22P02", () -> expectState("select 'abc'::int", "22P02"));
        op("err/fk delete parent 23503", () -> expectState("delete from jt_t where id = 101", "23503"));
        op("err/numeric overflow 22003", () -> expectState("insert into jt_t(id,n) values (8888, 1e30)", "22003"));
        op("timeout/setQueryTimeout + cancel", () -> { try (Statement s = c.createStatement()) { s.setQueryTimeout(1); try { s.execute("select count(*) from generate_series(1, 400000000) a"); return "finished"; } catch (SQLException e) { return e.getSQLState(); } } });
        op("conn/isValid + new connection + close", () -> { boolean v = c.isValid(2); try (Connection c2 = DriverManager.getConnection(url, p)) { return "valid=" + v + " c2=" + c2.isValid(2); } });
        op("conn/client info + setSchema/getSchema/getCatalog", () -> { c.setSchema("public"); return c.getSchema() + " " + c.getCatalog(); });
        op("conn/set statements (SET extra_float_digits, application_name)", () -> { exec("set application_name = 'rc'"); exec("set extra_float_digits = 3"); try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("show application_name")) { r.next(); return r.getString(1); } });
        op("conn/show server_version, TimeZone", () -> { try (Statement s = c.createStatement(); ResultSet r = s.executeQuery("show timezone")) { r.next(); return "tz ok"; } });

        c.close();
        System.out.println("SUMMARY ok=" + ok + " fail=" + fails);
    }
    static String expectState(String sql, String want) throws SQLException {
        try (Statement s = c.createStatement()) { s.execute(sql); throw new SQLException("NO ERROR, wanted " + want, "NONE"); }
        catch (SQLException e) { if (!want.equals(e.getSQLState())) throw new SQLException("state " + e.getSQLState() + " want " + want + ": " + e.getMessage(), e.getSQLState()); return e.getSQLState(); }
    }
}
